package com.example.proyectolp.service;
import com.example.proyectolp.repository.CreditLedgerRepository;import java.math.BigDecimal;import java.time.LocalDate;
public class CreditService {private final CreditLedgerRepository ledger;public CreditService(SupabaseService db){ledger=new CreditLedgerRepository(db);}public boolean habit(long id,LocalDate date,boolean completed,LocalDate today)throws Exception{int n=CreditRules.habit(completed,date,today);return n>0&&ledger.insert("habito",n,"Completar hábito",CreditRules.habitKey(id,date));}public boolean task(long id,boolean project)throws Exception{return ledger.insert(project?"tarea_proyecto":"tarea",CreditRules.task(project),"Completar tarea",CreditRules.taskKey(id));}public boolean stage(long id)throws Exception{return ledger.insert("etapa_proyecto",CreditRules.stage(),"Completar etapa",CreditRules.stageKey(id));}public int goalContribution(long id,BigDecimal target,BigDecimal oldValue,BigDecimal newValue)throws Exception{int count=CreditRules.crossedGoalMilestones(target,oldValue,newValue),awarded=0;for(int ordinal=1;ordinal<=count;ordinal++){int milestone=CreditRules.goalMilestoneNumber(target,oldValue,newValue,ordinal);if(ledger.insert("meta_ahorro",1,"Hito de ahorro "+milestone,CreditRules.goalKey(id,milestone)))awarded++;}return awarded;}}
